       "hostConfig": {
         "networkMode": "my-network"
       }
     }
   }
   ```

7. Create a `plugins/index.js` file in the `cypress/plugins` folder:

   ```
   module.exports = (on, config) => {
     require('cypress-docker-plugin')(on, config);
     return config;
   };
   ```

8. Create a `support/index.js` file in the `cypress/support` folder:

