void move_snake(Game *game, int direction) {
    int head_x = game->snake.x;
    int head_y = game->snake.y;

    switch (direction) {
        case 0: // haut
            head_y -= 20;
            break;
        case 1: // droite
            head_x += 20;
            break;
        case 2: // bas
            head_y += 20;
            break;
        case 3: // gauche
            head_x -= 20;
            break;
    }

    // vérifier si le mouvement est valide
    if (head_x < 0 || head_x >= game->width || head_y < 0 || head_y >= game->height) {
        game->game_over = true;
        return;
    }

    // vérifier si le serpent se mord la queue
    for (int I = 0; I < game->snake.length - 1; i++) {
        if (game->snake.body[i].x == head_x && game->snake.body[i].y == head_y) {
            game->game_over = true;
            return;
        }
    }

    // placer la tête du serpent en nouvelle position
    game->snake.x = head_x;
    game->snake.y = head_y;

    // ajouter un nouveau segment au serpent
    int *new_body = realloc(game->snake.body, (game->snake.length + 1) * sizeof(int *));
    game->snake.body = new_body;
    game->snake.body[game->snake.length] = (int[]) { game->snake.x, game->snake.y };

    game->snake.length++;
}
```

- Cette fonction utilise la valeur de direction pour déterminer la nouvelle position de la tête du serpent. Elle vérifie également si le mouvement est valide, si le serpent se mord la queue, et ajoute un nouveau segment au serpent.

